+type Task = {
+  id: string;
+  duration: number;
+  dependsOn: string[];
+};
+
+type Plan = {
+  order: string[];
+  layers: string[][];
+  earliest: Record<string, { start: number; finish: number }>;
+  totalDuration: number;
+  criticalPath: string[];
+};
+
+function fail(message: string): never {
+  throw new Error(message);
+}
+
+function validate(input: unknown): Task[] {
+  if (typeof input !== "object" || input === null || Array.isArray(input)) {
+    fail("Invalid schema: root must be an object.");
+  }
+  const tasks = (input as { tasks?: unknown }).tasks;
+  if (!Array.isArray(tasks)) fail("Invalid schema: tasks must be an array.");
+
+  const ids = new Set<string>();
+  const parsed = tasks.map((value, index): Task => {
+    if (typeof value !== "object" || value === null || Array.isArray(value)) {
+      fail(`Invalid schema: tasks[${index}] must be an object.`);
+    }
+    const task = value as TaskInput;
+    if (typeof task.id !== "string" || task.id.length === 0) {
+      fail(`Invalid schema: tasks[${index}].id must be a non-empty string.`);
+    }
+    if (ids.has(task.id)) fail(`Invalid schema: duplicate task id '${task.id}'.`);
+    ids.add(task.id);
+    if (typeof task.duration !== "number" || !Number.isFinite(task.duration) || task.duration < 0) {
+      fail(`Invalid schema: tasks[${index}].duration must be a finite non-negative number.`);
+    }
+    const dependsOn = task.dependsOn ?? [];
+    if (!Array.isArray(dependsOn) || dependsOn.some((id) => typeof id !== "string")) {
+      fail(`Invalid schema: tasks[${index}].dependsOn must be an array of strings.`);
+    }
+    if (new Set(dependsOn).size !== dependsOn.length) {
+      fail(`Invalid schema: tasks[${index}].dependsOn must not contain duplicates.`);
+    }
+    if (dependsOn.includes(task.id)) fail(`Invalid schema: task '${task.id}' cannot depend on itself.`);
+    return { id: task.id, duration: task.duration, dependsOn };
+  });
+
+  for (const task of parsed) {
+    for (const dependency of task.dependsOn) {
+      if (!ids.has(dependency)) fail(`Invalid schema: task '${task.id}' depends on unknown task '${dependency}'.`);
+    }
+  }
+  return parsed;
+}
+
+function findCycle(tasks: Map<string, Task>): string[] | undefined {
+  const state = new Map<string, "visiting" | "done">();
+  const path: string[] = [];
+  const visit = (id: string): string[] | undefined => {
+    const current = state.get(id);
+    if (current === "visiting") return [...path.slice(path.indexOf(id)), id];
+    if (current === "done") return undefined;
+    state.set(id, "visiting");
+    path.push(id);
+    for (const dependency of [...tasks.get(id)!.dependsOn].sort()) {
+      const cycle = visit(dependency);
+      if (cycle) return cycle;
+    }
+    path.pop();
+    state.set(id, "done");
+    return undefined;
+  };
+  for (const id of [...tasks.keys()].sort()) {
+    const cycle = visit(id);
+    if (cycle) return cycle;
+  }
+  return undefined;
+}
+
+function plan(tasks: Task[]): Plan {
+  const byId = new Map(tasks.map((task) => [task.id, task]));
+  const cycle = findCycle(byId);
+  if (cycle) fail(`Cycle detected: ${cycle.join(" -> ")}`);
+
+  const dependents = new Map<string, string[]>();
+  const remaining = new Map<string, number>();
+  for (const task of tasks) {
+    remaining.set(task.id, task.dependsOn.length);
+    for (const dependency of task.dependsOn) {
+      const children = dependents.get(dependency) ?? [];
+      children.push(task.id);
+      dependents.set(dependency, children);
+    }
+  }
+
+  const ready = tasks.filter((task) => task.dependsOn.length === 0).map((task) => task.id).sort();
+  const order: string[] = [];
+  while (ready.length > 0) {
+    const id = ready.shift()!;
+    order.push(id);
+    for (const child of (dependents.get(id) ?? []).sort()) {
+      const count = remaining.get(child)! - 1;
+      remaining.set(child, count);
+      if (count === 0) {
+        ready.push(child);
+        ready.sort();
+      }
+    }
+  }
+
+  const earliest: Plan["earliest"] = {};
+  const layers: string[][] = [];
+  const pathTo = new Map<string, string[]>();
+  let totalDuration = 0;
+  let criticalPath: string[] = [];
+  for (const id of order) {
+    const task = byId.get(id)!;
+    let start = 0;
+    let layer = 0;
+    let predecessor: string | undefined;
+    for (const dependency of task.dependsOn) {
+      const timing = earliest[dependency];
+      if (timing.finish > start || (timing.finish === start && (predecessor === undefined || dependency < predecessor))) {
+        start = timing.finish;
+        predecessor = dependency;
+      }
+      layer = Math.max(layer, (layers.findIndex((tasksInLayer) => tasksInLayer.includes(dependency)) + 1));
+    }
+    const finish = start + task.duration;
+    earliest[id] = { start, finish };
+    while (layers.length <= layer) layers.push([]);
+    layers[layer].push(id);
+    const path = predecessor ? [...pathTo.get(predecessor)!, id] : [id];
+    pathTo.set(id, path);
+    if (finish > totalDuration || (finish === totalDuration && comparePaths(path, criticalPath) < 0)) {
+      totalDuration = finish;
+      criticalPath = path;
+    }
+  }
+  for (const tasksInLayer of layers) tasksInLayer.sort();
+  return { order, layers, earliest, totalDuration, criticalPath };
+}
+
+function comparePaths(left: string[], right: string[]): number {
+  for (let index = 0; index < Math.min(left.length, right.length); index += 1) {
+    const comparison = left[index].localeCompare(right[index]);
+    if (comparison !== 0) return comparison;
+  }
+  return left.length - right.length;
+}
+
+function main(args: string[]): void {
+  if (args.length !== 2 || args[0] !== "plan") fail("Usage: bun run src/cli.ts plan INPUT.json");
+  let input: unknown;
+  try {
+    input = JSON.parse(Bun.file(args[1]).textSync());
+  } catch (error) {
+    fail(`Unable to read valid JSON from '${args[1]}': ${(error as Error).message}`);
+  }
+  console.log(JSON.stringify(plan(validate(input))));
+}
+
+try {
+  main(Bun.argv.slice(2));
+} catch (error) {
+  console.error((error as Error).message);
+  process.exit(1);
+}
